        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => ui_s((ui_t(ui_eq($v_size, 'compact')) ? '0' : '2')), 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_1])|noescape}
      {/if}
    {/capture}
    {=ui_include('blocks/panel.latte', ['p' => ['title' => $v_title, 'description' => $v_text, 'id' => $v_id, 'className' => ui_cnv([(ui_t(ui_eq($v_tone, 'muted')) ? 'bg-muted' : '')])], 'children' => $c_2])|noescape}
  {/capture}
  {=ui_include('ui/container/container.latte', ['p' => ['Class' => 'mx-auto w-full max-w-6xl px-4 py-8', 'Attrs' => ui_attrs(['data-slot', 'container'])], 'children' => $c_3])|noescape}
{/capture}
{=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'section', 'Attrs' => ui_attrs(['aria-labelledby', (ui_t($v_landmarkLabel) ? null : (ui_t(ui_and([$v_title, $v_id])) ? ui_tpl('{0}-t', [$v_id]) : null)), 'data-testid', 'panel-section', 'aria-label', $v_landmarkLabel])], 'children' => $c_4])|noescape}
